test('invoiceTotals with voucher applied', () => {
  const r1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'DEV-HOUR', qty: 5 },
    ],
  });
  const r2 = applyVoucher(r1.value, { code: 'PROMO', amount: 25000 });
  const totals = invoiceTotals(r2.value);
  assert.equal(totals.voucher, 25000);
  assert.equal(totals.subtotal, totals.subtotal);
  assert.equal(totals.total, totals.subtotal - totals.discount + totals.vat - 25000);
});

